import 'package:test/test.dart';
import 'package:zxing2/oned.dart';

/// @author Daisuke Makiuchi
void main() {
  void doTest(String expectedResult, String encodedResult) {
    var sut = Code93Reader();
    var matrix = BitMatrix.parseString(encodedResult, '1', '0');
    var row = BitArray(matrix.width);
    row = matrix.getRow(0, row);
    var result = sut.decodeRow(0, row, DecodeHints());
    expect(result.text, expectedResult);
  }

  test('Decode', () {
    doTest('Code93!\n\$%/+ :\u001b;[{\u007f\u0000@`\u007f\u007f\u007f',
        '');
  });
}
